contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint seed) public payable {
        require(seed >= 0, "seed must be non-negative");
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balAfter = address(c).balance;
        assert(balAfter == 0 && address(owner).balance >= balBefore);
    }
}

