        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint balBefore = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(balAfter == 0 && address(owner).balance >= balBefore);
    }

